// Illustrations for empty/zero states and any other spot that wants art. The full unDraw set (MIT)
// lives in public/assets/illustrations, sorted into category folders, and is generated by
// `node --experimental-strip-types scripts/fetchIllustrations.ts`.
//
// Files are served as plain assets and loaded by <img>, so nothing is bundled and an illustration that
// never renders costs no bytes. Their palette runs the brand axis (navy -> cyan, the same axis as the
// ramps in index.css), fixed and legible on both themes, so there is no light/dark variant to pick
// between.
//
// Refer to one either by an alias below - a role rather than a subject, so swapping the art is a
// one-line change in the script - or by its `category/slug` path (`"work-office/job-offers"`), checked
// against the generated union. Browse the categories in
// web/public/assets/illustrations/README.md, or search index.json via loadIllustrationIndex().

import { ALIAS_PATHS, type IllustrationPath } from "./illustrationPaths";

export { ALIAS_PATHS, ILLUSTRATION_CATEGORIES, ILLUSTRATION_COUNT, type IllustrationPath } from "./illustrationPaths";

export type IllustrationAlias = keyof typeof ALIAS_PATHS;
export type Illustration = IllustrationAlias | IllustrationPath;

export function illustrationSrc(name: Illustration): string {
  const path = (ALIAS_PATHS as Record<string, IllustrationPath>)[name] ?? (name as IllustrationPath);
  return illustrationUrl(path);
}

// Same URL for a path that only exists at runtime - one the server stored (a kudos card) or one the user just
// picked out of the index - where there is nothing for the union to check. A path naming no file simply fails
// the <img> load, so callers give it an onError fallback rather than validating here.
export function illustrationUrl(path: string): string {
  return `/assets/illustrations/${path}.svg`;
}

// Picker index, fetched on first use and cached for the tab. Only a browse/search UI needs this - an
// ordinary <EmptyState illustration=…> should never pull 1700 titles over the wire.
export type IllustrationMeta = {
  slug: string;
  dir: string;
  title: string;
  keywords?: string[];
  aspect?: number;
};

let indexPromise: Promise<IllustrationMeta[]> | undefined;

export function loadIllustrationIndex(): Promise<IllustrationMeta[]> {
  indexPromise ??= fetch("/assets/illustrations/index.json")
    .then((r) => (r.ok ? (r.json() as Promise<IllustrationMeta[]>) : Promise.reject(new Error(`index ${r.status}`))))
    .catch((e) => {
      indexPromise = undefined; // let a later caller retry
      throw e;
    });
  return indexPromise;
}

// How well one illustration answers one search word. Lower is better, -1 is no match. Ranked so a plain word
// match on the title beats one buried in keywords, and a category-name match comes last (it matches dozens).
export function illustrationScore(m: IllustrationMeta, term: string): number {
  const title = m.title.toLowerCase();
  if (title === term) return 0;
  if (title.startsWith(term)) return 1;
  if (title.includes(term)) return 2;
  if (m.slug.includes(term)) return 3;
  if ((m.keywords ?? []).some((k) => k.toLowerCase().startsWith(term))) return 4;
  if ((m.keywords ?? []).some((k) => k.toLowerCase().includes(term))) return 5;
  if (m.dir.includes(term)) return 6;
  return -1;
}

// Function words, plus the handful of words a workplace post is always full of - they match hundreds of
// illustrations each and would drown out the words that actually say what the post is about.
const STOP_WORDS = new Set(
  ("a an the and or but if then than that this these those is are was were be been being am do does did doing have has had " +
   "i you he she it we they me him her us them my your our their its of in on at to for from by with without into over under " +
   "about as so no not all any some more most just will would can could should may might must there here when what which who " +
   "please kindly thanks thank hi hello everyone team-wide dear regards note update updates new news today tomorrow yesterday").split(" "),
);

// Words worth searching the catalogue for, taken from whatever the author has typed so far. Plurals are tried in
// their singular form too, so "holidays" finds "Holiday".
function searchWords(text: string): string[] {
  const out: string[] = [];
  const seen = new Set<string>();
  for (const raw of text.toLowerCase().split(/[^a-z0-9]+/)) {
    if (raw.length < 3 || STOP_WORDS.has(raw)) continue;
    for (const w of raw.endsWith("s") && raw.length > 4 ? [raw, raw.slice(0, -1)] : [raw]) {
      if (seen.has(w)) continue;
      seen.add(w);
      out.push(w);
    }
    if (out.length >= 16) break; // a long post is described by its opening, not by every word in it
  }
  return out;
}

// Art to offer for a piece of writing: the illustrations whose title/keywords its words point at, best first.
// Every matched word adds weight, so an entry that answers two of them outranks one that answers a single word
// well - "diwali holiday party" should land on a festival, not on the first thing tagged "party".
//
// At most two per category, because a strip of six near-identical office scenes is one suggestion, not six.
export function suggestIllustrations(index: IllustrationMeta[], text: string, limit = 6): IllustrationMeta[] {
  const words = searchWords(text);
  if (!words.length || limit <= 0) return [];
  const scored: { m: IllustrationMeta; weight: number }[] = [];
  for (const m of index) {
    let weight = 0;
    for (const w of words) {
      const s = illustrationScore(m, w);
      if (s >= 0) weight += 7 - s;
    }
    if (weight > 0) scored.push({ m, weight });
  }
  // Shorter titles win ties: they name one thing ("Party") rather than a scene ("Party at the office"), which
  // is what reads as a sticker.
  scored.sort((a, b) => b.weight - a.weight || a.m.title.length - b.m.title.length || a.m.title.localeCompare(b.m.title));
  const perDir = new Map<string, number>();
  const out: IllustrationMeta[] = [];
  for (const { m } of scored) {
    const n = perDir.get(m.dir) ?? 0;
    if (n >= 2) continue;
    perDir.set(m.dir, n + 1);
    out.push(m);
    if (out.length >= limit) break;
  }
  return out;
}

export function illustrationPath(meta: IllustrationMeta): IllustrationPath {
  return `${meta.dir}/${meta.slug}` as IllustrationPath;
}
